{
  "cvars": {
    "ivs": [
      {
        "description": "Use of live bait during the fishing trip (binary indicator: 1 = used live bait, 0 = did not). Hypothesized to increase catch rate.",
        "columns": [
          "LiveBait"
        ]
      },
      {
        "description": "Whether the group had a camper with them during the visit (binary indicator: 1 = had camper, 0 = no camper). Could affect mobility/time spent and therefore catch rate.",
        "columns": [
          "HasCamper"
        ]
      }
    ],
    "dv": {
      "description": "Count of fish caught during the visit. Modeled as a count outcome with park-hours as exposure to estimate fish caught per hour (rate).",
      "columns": [
        "FishCaught"
      ]
    },
    "controls": [
      {
        "description": "Number of adults in the group (numeric). Controls for group composition which may affect effort and catch.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "NumAdults"
        ]
      },
      {
        "description": "Number of children in the group (numeric). Controls for group composition which may affect effort and catch.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "NumChildren"
        ]
      },
      {
        "description": "Number of hours the group spent in the park (continuous, >0). Used as the exposure variable (log(Hours)) in the count model so coefficients reflect change in catch rate per hour.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Hours",
          "logHours"
        ]
      },
      {
        "description": "Observed catch rate (fish per hour). Derived variable for descriptive analysis and diagnostics (not used as dependent variable in GLM which uses counts with exposure).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "FishPerHour"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Rename columns to meaningful names\n    df = df.rename(columns={\n        'feature1': 'FishCaught',\n        'feature2': 'LiveBait',\n        'feature3': 'HasCamper',\n        'feature4': 'NumAdults',\n        'feature5': 'NumChildren',\n        'feature6': 'Hours'\n    }).copy()\n\n    # Keep only rows with non-missing values for key variables\n    df = df.dropna(subset=['FishCaught', 'LiveBait', 'HasCamper', 'NumAdults', 'NumChildren', 'Hours'])\n\n    # Ensure numeric types\n    df['FishCaught'] = pd.to_numeric(df['FishCaught'], errors='coerce')\n    df['LiveBait'] = pd.to_numeric(df['LiveBait'], errors='coerce').astype(int)\n    df['HasCamper'] = pd.to_numeric(df['HasCamper'], errors='coerce').astype(int)\n    df['NumAdults'] = pd.to_numeric(df['NumAdults'], errors='coerce')\n    df['NumChildren'] = pd.to_numeric(df['NumChildren'], errors='coerce')\n    df['Hours'] = pd.to_numeric(df['Hours'], errors='coerce')\n\n    # Drop any rows made NA by coercion\n    df = df.dropna(subset=['FishCaught', 'LiveBait', 'HasCamper', 'NumAdults', 'NumChildren', 'Hours'])\n\n    # Filter out non-positive hours (cannot use as exposure)\n    df = df[df['Hours'] > 0].copy()\n\n    # Derived columns\n    # FishPerHour: descriptive rate (float)\n    df['FishPerHour'] = df['FishCaught'] / df['Hours']\n\n    # Log of hours used as offset in count models\n    df['logHours'] = np.log(df['Hours'])\n\n    # Optionally create group size for diagnostics (not used directly in main model)\n    df['GroupSize'] = df['NumAdults'] + df['NumChildren']\n\n    # Final columns required for modeling: FishCaught, LiveBait, HasCamper, NumAdults, NumChildren, Hours, logHours, FishPerHour\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> Any:\n    # Build design matrix (predictors). Use additive model for rate of fish caught per hour.\n    X = df[['LiveBait', 'HasCamper', 'NumAdults', 'NumChildren']].copy()\n    X = sm.add_constant(X, has_constant='add')\n\n    # Response: count of fish caught. Use Negative Binomial GLM with log(Hours) as offset to model rate per hour.\n    # If NegativeBinomial family is unavailable in the environment, fallback to Poisson and warn user.\n    try:\n        family = sm.families.NegativeBinomial()\n    except Exception:\n        family = sm.families.Poisson()\n\n    model_glm = sm.GLM(endog=df['FishCaught'], exog=X, family=family, offset=df['logHours'])\n    results = model_glm.fit()\n\n    # Return the fitted results object (has .summary(), .params, .bse, etc.)\n    return results\n"
}
